import DeliveryRouteSummary from './DeliveryRouteSummary.jsx';
import React, {useEffect,useRef,useState,useMemo} from 'react';
import {Activity,ArrowDownLeft,ArrowRight,ArrowUpRight,Bell,Box,Building2,Check,CheckCircle2,ChevronDown,ChevronRight,Clock,Command,Compass,Download,Expand,Eye,FileCheck2,Flame,Focus,History,LayoutDashboard,Leaf,Lightbulb,Loader2,LocateFixed,LockKeyhole,LogOut,MapPin,MoreHorizontal,Package,PanelRightClose,Pause,Play,Plus,Power,Radio,RotateCcw,Route,Search,Send,Settings2,Shield,ShieldAlert,SlidersHorizontal,Sparkles,Sun,Terminal,Truck,Users,Wifi,WifiOff,Wind,X,Zap} from 'lucide-react';
