const icons={light:Lightbulb,hvac:Wind,window:Box,sensor:Radio,robot:Shield,drone:Send,delivery_robot:Truck};
const types={light:'智能照明',hvac:'中央空调',window:'智能窗户',sensor:'环境传感器',robot:'巡检机器人',drone:'配送无人机',delivery_robot:'配送机器人'};
const statusText={online:'在线',offline:'离线',running:'运行中',alert:'告警',pending:'待审批',pending_approval:'待审批',queued:'待调度',paused:'已暂停',returning:'返航中',completed:'已完成',cancelled:'已取消',delivered:'待签收',signed:'已签收',archived:'已归档',exception:'异常待处理',detected:'待确认',confirmed:'已确认',dispatched:'处理中',resolved:'待复核',reviewed:'已复核',approved:'已通过',rejected:'已驳回',withdrawn:'已撤回',succeeded:'已执行',failed:'执行失败',timed_out:'已超时',present:'正常出勤',late:'迟到',early:'早退',absent:'缺勤',review:'待复核'};
const roles={super_admin:'超级管理员',park_admin:'园区管理员',security:'安保人员',ops:'运维人员',approver:'审批人员',user:'普通用户'};
export {Login, DevicePage, SecurityPage, DeliveryPage, AttendancePage, ReportsPage, Drawer, ActionModal, Modal, Badge, IconButton};
const tabs=[['hub','AI 中枢',Sparkles],['overview','园区总览',LayoutDashboard],['devices','设备控制',SlidersHorizontal],['security','安防消防',Shield],['delivery','无人配送',Send],['oa','协同办公',FileCheck2],['attendance','考勤巡查',Users],['reports','运行报告',Activity]];
const layerItems=[['overview','综合',Building2],['security','安防',Shield],['energy','能耗',Zap],['fire','消防',Flame],['devices','设备',Radio],['delivery','配送',Send]];
const fmtTime=v=>v?new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'—';
const fmtDate=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const num=v=>Number(v||0).toLocaleString('zh-CN');
const Badge=({status,children})=><span className={'badge '+status}><i/>{children||statusText[status]||status}</span>;
const IconButton=({icon:Icon,title,...rest})=><button className="icon-button" title={title} aria-label={title} {...rest}><Icon size={17}/></button>;
function Brand(){return <div className="brand"><div className="brand-symbol"><svg viewBox="0 0 40 40"><path d="M9 27c7-1 10-8 12-14 1-4 6-7 10-6-3 2-6 5-6 9 0 4 1 5 5 7-5 0-9 1-12 5l-9 1M7 20c4 3 7 4 12 3M12 13c3 3 6 5 10 6" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round"/></svg></div><div><strong>白鹭湾<span>AI 中枢</span></strong><small>BAILUWAN · COMMAND CENTER</small></div></div>}
function Sparkline({values=[25,30,28,42,35,44,45,38,53,48,60],color='#8ee0cb',fill=false}){const max=Math.max(...values,1),min=Math.min(...values)*.75;const pts=values.map((v,i)=>`${i/(values.length-1)*140},${38-(v-min)/(max-min||1)*32}`).join(' ');return <svg viewBox="0 0 140 44" preserveAspectRatio="none" className="sparkline"><defs><linearGradient id={'g'+color.slice(1)} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity=".22"/><stop offset="100%" stopColor={color} stopOpacity="0"/></linearGradient></defs>{fill&&<polygon points={'0,44 '+pts+' 140,44'} fill={`url(#g${color.slice(1)})`}/>}<polyline points={pts} fill="none" stroke={color} strokeWidth="1.8" vectorEffect="non-scaling-stroke"/></svg>}
function Empty({text='暂无记录',icon:Icon=Box}){return <div className="empty"><Icon size={30}/><strong>{text}</strong><span>新的业务记录将在这里同步呈现</span></div>}
function Modal({title,subtitle,onClose,children,wide=false}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title}><div className="modal-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><IconButton icon={X} title="关闭" onClick={onClose}/></div>{children}</section></div>}
function Login({onLogin}){const [username,setUsername]=useState('admin'),[password,setPassword]=useState('Bailuwan2026!'),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');try{await api('/login',{username,password});await onLogin();}catch(e){setError(e.message);}finally{setBusy(false);}}return <div className="login-screen"><div className="login-art"><Brand/><div className="login-art-copy"><span className="eyebrow">CONNECTED NATURE. INTELLIGENT FUTURE.</span><h1>与自然共生，<br/>让智慧发生。</h1><p>成都市白鹭湾园区 AI 中枢 v1.1<br/>在一个数字空间里，感知、协同、掌控每一刻。</p><div className="login-grid-art"><div/><div/><div/><div/><div/></div><span className="login-coordinates">CHENGDU · 30.568° N / 104.176° E · 示意坐标</span></div></div><div className="login-panel"><span className="tag"><i/> 本地数字孪生演示</span><h2>欢迎回到白鹭湾</h2><p>登录中央控制系统，开启园区全局视野。</p><form onSubmit={submit}><label>访问角色<select value={username} onChange={e=>setUsername(e.target.value)}><option value="admin">超级管理员 · admin</option><option value="park">园区管理员 · park</option><option value="security">安保人员 · security</option><option value="ops">运维人员 · ops</option><option value="approver">审批人员 · approver</option><option value="viewer">普通用户 · viewer</option></select></label><label>登录密码<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></label>{error&&<div className="inline-error">{error}</div>}<button className="primary login-submit" disabled={busy}>{busy?<Loader2 className="spin" size={18}/>:<ArrowRight size={18}/>}进入园区控制中心</button></form><div className="login-note"><Shield size={18}/><p>内置演示账号，默认密码已填入。<br/>所有设备与场景均为模拟，不连接现实设备。</p></div></div><footer>BAILUWAN SMART PARK <span>数字空间 · 有序共生</span> © 2026</footer></div>}

export default function App(){
  const [data,setData]=useState(null),[loading,setLoading]=useState(true),[tab,setTab]=useState('hub'),[layer,setLayer]=useState('overview'),[selection,setSelection]=useState(null),[focus,setFocus]=useState(null),[reset,setReset]=useState(0),[view,setView]=useState('perspective'),[floor,setFloor]=useState(0),[modal,setModal]=useState(null),[agentOpen,setAgentOpen]=useState(false),[toasts,setToasts]=useState([]),[connected,setConnected]=useState(false),[busy,setBusy]=useState(false),[search,setSearch]=useState(''),[clock,setClock]=useState(new Date()),[sceneReady,setSceneReady]=useState(false),[initialError,setInitialError]=useState('');
  const sceneRef=useRef(null),refreshing=useRef(false);
  const notify=(message,type='success')=>{const id=key();setToasts(v=>[...v.slice(-3),{id,message,type}]);setTimeout(()=>setToasts(v=>v.filter(x=>x.id!==id)),6000);};
  async function refresh(){if(refreshing.current)return;refreshing.current=true;try{const result=await api('/bootstrap');setData(result);setInitialError('');}catch(e){if(e.status===401)setData(null);else {setInitialError(e.message);if(data)notify(e.message,'error');}}finally{refreshing.current=false;setLoading(false);}}
  useEffect(()=>{refresh();const timer=setInterval(()=>setClock(new Date()),1000);return()=>clearInterval(timer);},[]);
  const userId=data?.user?.id;
  useEffect(()=>{if(!userId)return;const stream=new EventSource('/api/events');stream.onopen=()=>setConnected(true);stream.addEventListener('update',()=>refresh());stream.onmessage=()=>refresh();stream.onerror=()=>setConnected(false);const poll=setInterval(refresh,10000);return()=>{stream.close();clearInterval(poll);};},[userId]);
  useEffect(()=>{const handler=e=>{if(e.key==='Escape'){setModal(null);setSelection(null);setAgentOpen(false);}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[]);
  async function act(path,body,message='操作已提交'){setBusy(true);try{const result=await api(path,body);await refresh();if(message)notify(message);return result;}catch(e){notify(e.message,'error');return null;}finally{setBusy(false);}}
  const openSelection=s=>{setSelection(s);setFocus(s);setFloor(0);};
  const goLocation=(buildingId)=>{setTab('overview');setFocus({kind:'building',id:buildingId});setSelection({kind:'building',id:buildingId});};
  if(loading)return <div className="app-loading"><Brand/><Loader2 size={28} className="spin"/><p>正在建立园区数字连接…</p></div>;
  if(!data)return <>{initialError&&<div className="connection-error">{initialError}<button onClick={refresh}>重试连接</button></div>}<Login onLogin={refresh}/></>;
  const {devices=[],buildings=[],alerts=[],patrols=[],deliveries=[],approvals=[],attendance=[],automations=[],audit=[],commands=[],energy=[],agentRuns=[]}=data;
  const takeover=data.takeover||{active:false};
  const activeAlerts=alerts.filter(a=>a.status!=='archived'),activeCritical=activeAlerts.filter(a=>a.severity==='critical');
  const activeDeliveries=deliveries.filter(d=>['running','queued','pending_approval','paused'].includes(d.status));
  const online=devices.filter(d=>d.status!=='offline').length,rate=devices.length?(online/devices.length*100).toFixed(1):'0';
  const done=patrols.filter(p=>p.status==='completed').length;
  const energyValues=energy.map(e=>e.value??e.kwh??0);const values=energyValues.length>1?energyValues:[22,28,26,30,34,42,38,44,40,35,31,28];
  const canControl=['super_admin','park_admin','ops'].includes(data.user.role),canSecurity=['super_admin','park_admin','security'].includes(data.user.role),canApprove=['super_admin','park_admin','approver'].includes(data.user.role),canTakeover=data.user.role==='super_admin';
  const selected=selection?.kind==='device'?devices.find(d=>d.id===selection.id):selection?.kind==='building'?buildings.find(b=>b.id===selection.id):selection?.kind==='alert'?alerts.find(a=>a.id===selection.id):null;
  const searches=search.trim()?[...buildings.map(b=>({...b,kind:'building',hint:'建筑'})),...devices.map(d=>({...d,kind:'device',hint:types[d.type]})),...alerts.map(a=>({...a,name:a.title,kind:'alert',hint:'事件'}))].filter(x=>(x.name+x.id).toLowerCase().includes(search.toLowerCase())).slice(0,7):[];
  const shared={data,act,busy,setModal,notify,goLocation,openSelection,canControl,canSecurity,canApprove};
  return <div className={'app '+(takeover.active?'takeover-active':'')}>
    <header className="topbar"><Brand/><nav aria-label="主导航">{tabs.map(([id,title,Icon])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setSelection(null);}}><Icon size={17}/><span>{title}</span>{id==='oa'&&approvals.filter(a=>a.status==='pending').length>0&&<i className="nav-dot"/>}</button>)}</nav><div className="topbar-actions"><IconButton icon={Bell} title="查看待处理事件" onClick={()=>setTab('security')}/><div className="user-avatar">{data.user.name?.slice(0,1)||'管'}</div><div className="user-name"><strong>{data.user.name||'园区管理员'}</strong><small>{roles[data.user.role]}</small></div><IconButton icon={LogOut} title="退出登录" onClick={async()=>{await api('/logout',{});setData(null);}}/></div></header>
    {takeover.active&&<div className="takeover-banner"><ShieldAlert size={17}/><strong>人工接管生效</strong><span>{takeover.actor} · {fmtDate(takeover.at)} · Agent 与自动化已暂停，设备操作由授权人员执行</span><button onClick={()=>setModal({type:'takeover',release:true})}>检查并解除接管 <ArrowRight size={14}/></button></div>}
    <main>
      <div className="page-heading"><div><div className="eyebrow">BAILUWAN DIGITAL TWIN <span>/</span> {tab==='overview'?'LIVE OVERVIEW':'OPERATIONS CENTER'}</div><h1>{tabs.find(t=>t[0]===tab)?.[1]}<span className="live-label"><i/>{data.simulator?.connected?'实时运行':'模拟器离线'}</span></h1><p>{tab==='overview'?'一方生态，一城智慧。让园区的每一次变化，都清晰可见。':({hub:'从目标到执行，让设备、空间与人员协同响应。',devices:'统一感知设备状态，将每一条控制指令落实到执行回执。',security:'从异常发现到复核归档，让每一项处置有迹可循。',delivery:'连接园区最后一公里，让物资与服务有序抵达。',oa:'连接申请、决策与执行，让跨部门协同更进一步。',attendance:'关注到岗与巡查，只呈现工作所需的信息。',reports:'用可追溯的数据，理解园区当下与运行趋势。'}[tab])}</p></div><div className="heading-tools"><div className="weather"><Sun size={23}/><span>22°<small>成都 · 晴 / 模拟天气</small></span></div><div className="date-time"><strong>{clock.toLocaleTimeString('zh-CN',{hour12:false})}</strong><small>{clock.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',weekday:'short'})}</small></div><button className={'takeover-button '+(takeover.active?'is-active':'')} disabled={!canTakeover} title={canTakeover?'管理员身份确认后接管':'仅授权管理员可接管'} onClick={()=>setModal({type:'takeover',release:takeover.active})}><ShieldAlert size={16}/>{takeover.active?'接管中':'人工接管'}</button></div></div>
      {data.simulator&&!data.simulator.connected&&<div className="connection-banner"><Radio size={14}/>设备模拟器尚未连接；当前读数为最近快照，指令将等待回执或超时。</div>}{!connected&&<div className="connection-banner"><WifiOff size={14}/>实时流暂未连接，正在重连；页面每 10 秒同步一次。<button onClick={refresh}>立即刷新</button></div>}
      {tab==='overview'?<>
        <div className="metrics-row"><Metric icon={Radio} label="设备在线率" value={rate} unit="%" foot={`${online} / ${devices.length} 台设备在线`} trend="稳定运行"/><Metric icon={ShieldAlert} label="待处置事件" value={activeAlerts.length.toString().padStart(2,'0')} foot={`${activeCritical.length} 项高风险需关注`} accent="amber" trend="实时监测"/><Metric icon={Zap} label="今日累计用电" value={num(Math.round(values.reduce((a,b)=>a+b,0)))} unit="kWh" foot="模拟表计 · 累计采样" spark={values}/><Metric icon={Route} label="巡检任务完成" value={done} unit={'/ '+patrols.length} foot={`${patrols.filter(p=>p.status==='running').length} 个机器人正在巡检`} trend="自主巡航"/><Metric icon={Package} label="进行中配送" value={activeDeliveries.length.toString().padStart(2,'0')} foot={`${deliveries.filter(d=>['signed','archived'].includes(d.status)).length} 笔已签收订单`} trend="全程可追踪"/></div>
        <div className="overview-grid"><section className="scene-card" ref={sceneRef}><div className="scene-heading"><div><span className="section-eyebrow">PARK EXPLORER</span><h2>白鹭湾 · 数字孪生园区 <span>3D LIVE</span></h2></div><div className="scene-search"><Search size={15}/><input aria-label="搜索建筑设备或事件" placeholder="搜索建筑、设备、事件" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button onClick={()=>setSearch('')}><X size={13}/></button>}{search&&<div className="search-results">{searches.length?searches.map(s=><button key={s.kind+s.id} onClick={()=>{openSelection({kind:s.kind,id:s.id});setSearch('');}}><MapPin size={14}/><span>{s.name}<small>{s.hint} · {s.id}</small></span><ArrowRight size={14}/></button>):<p>没有匹配结果</p>}</div>}</div></div>
          <div className="scene-viewport"><ParkScene buildings={buildings} devices={devices} patrols={patrols} deliveries={deliveries} alerts={activeAlerts} layer={layer} selectedId={selection?.id} onSelect={openSelection} onReady={()=>setSceneReady(true)} focusTarget={focus} resetKey={reset} view={view} floor={floor} showLabels={true}/>{!sceneReady&&<div className="scene-loading"><Loader2 className="spin"/>正在构建园区空间…</div>}<div className="layer-switcher">{layerItems.map(([id,name,Icon])=><button key={id} className={layer===id?'active':''} onClick={()=>setLayer(id)}><Icon size={16}/><span>{name}</span></button>)}</div><div className="scene-note"><span><i/> SIMULATION TWIN</span><h3>以数字，洞见园区</h3><p>成都 · 白鹭湾生态科技园</p><small>程序化园区示意模型 · 非真实测绘数据</small></div><div className="scene-tools"><button className={view==='perspective'?'active':''} onClick={()=>setView('perspective')}>3D</button><button className={view==='top'?'active':''} onClick={()=>setView('top')}>2D</button><IconButton icon={Focus} title="复位视角" onClick={()=>{setReset(v=>v+1);setFocus(null);setSelection(null);setFloor(0);}}/><IconButton icon={Expand} title="切换场景全屏" onClick={()=>document.fullscreenElement?document.exitFullscreen():sceneRef.current?.requestFullscreen?.()}/></div><div className="scene-compass"><Compass size={35}/><span>N</span></div><div className="map-legend"><span><i className="mint"/>在线设备</span><span><i className="amber"/>待处置事件</span><span><i className="red"/>高风险区域</span><em>拖动旋转 · 滚轮缩放 · 右键平移</em></div></div><div className="scene-footer"><span><MapPin size={14}/>园区总览 <ChevronRight size={13}/> {buildings.length} 栋建筑 <span className="separator">|</span> 空间坐标已校准</span><span><i className="pulse-dot"/> 场景与设备状态实时同步</span></div></section>
        <aside className="overview-aside"><section className="agent-card"><div className="agent-orb"><Sparkles size={23}/></div><div><div className="agent-title">园区智能助手<span>BETA</span></div><p>{takeover.active?'人工接管中 · 智能代管已暂停':'正在守护园区的每一次运转'}</p></div><button onClick={()=>setTab('hub')}><span>{takeover.active?'查看接管状态':'编排园区任务'}</span><ArrowUpRight size={16}/></button><div className="agent-foot"><span><i/>规则模拟 · 权限受控</span><span>{agentRuns.length} 次调用记录</span></div></section>
        <section className="panel alerts-panel"><div className="panel-title"><h2>实时事件 <span className="count">{activeAlerts.length}</span></h2><button className="text-button" onClick={()=>setTab('security')}>全部 <ChevronRight size={14}/></button></div><div className="event-list">{activeAlerts.slice(0,3).map(a=><button className="event-item" key={a.id} onClick={()=>openSelection({kind:'alert',id:a.id})}><div className={'event-icon '+a.severity}>{a.type==='fire'?<Flame size={17}/>:a.type==='energy'?<Zap size={17}/>:<ShieldAlert size={17}/>}</div><div><strong>{a.title}</strong><p>{buildings.find(b=>b.id===a.buildingId)?.name||'公共区域'}<span>·</span>{fmtTime(a.createdAt)}</p><small>{a.drill?'演练事件 · ':''}{statusText[a.status]}</small></div><ChevronRight size={14}/></button>)}{!activeAlerts.length&&<Empty text="当前无待处置事件" icon={CheckCircle2}/>}</div><button className="panel-bottom-button" onClick={()=>setModal({type:'scenario'})}><Plus size={14}/> 创建模拟事件 / 消防演练</button></section>
        <section className="panel patrol-panel"><div className="panel-title"><h2>自主巡检</h2><span className="muted">{patrols.filter(p=>p.status==='running').length} 台运行中</span></div>{patrols.slice(0,2).map(p=><div className="mini-task" key={p.id}><div className="mini-task-top"><div className="robot-icon"><Shield size={18}/></div><div><strong>{p.name}</strong><small>{devices.find(d=>d.id===p.robotId)?.name||p.robotId}</small></div><Badge status={p.status}/></div><div className="progress-line"><span><i style={{width:p.progress+'%'}}/></span><b>{Math.round(p.progress||0)}%</b></div></div>)}<button className="text-button patrol-link" onClick={()=>setTab('security')}>进入巡检调度 <ArrowRight size={14}/></button></section></aside></div>
        <div className="overview-bottom"><section className="quick-actions"><div><span className="section-eyebrow">QUICK ACTIONS</span><strong>一键场景</strong></div>{[['work','上班模式',Sun],['off','下班模式',Power],['night','夜间值守',Shield],['eco','节能模式',Leaf]].map(([mode,name,Icon])=><button key={mode} disabled={!canControl} onClick={()=>setModal({type:'scene',mode,name})}><span><Icon size={19}/></span>{name}<ArrowUpRight size={13}/></button>)}</section><section className="daily-insight"><div className="insight-icon"><Leaf size={24}/></div><div><span>让每一度电，都有价值</span><p>查看分时用电，识别异常运行设备</p></div><button aria-label="查看能耗运行报告" onClick={()=>setTab('reports')}><ArrowRight size={18}/></button></section></div>
      </>:tab==='hub'?<HubPage {...shared}/>:tab==='devices'?<DevicePage {...shared}/>:tab==='security'?<SecurityPage {...shared}/>:tab==='delivery'?<DeliveryPage {...shared}/>:tab==='oa'?<OAPage {...shared}/>:tab==='attendance'?<AttendancePage {...shared}/>:<ReportsPage {...shared}/>}
      <footer className="system-footer"><span><i className={connected?'pulse-dot':'offline-dot'}/>{connected?'实时数据链路正常':'实时数据链路重连中'}<span className="separator">|</span>设备接入模式：模拟器<span className="separator">|</span>{takeover.active?'控制权：人工接管':'控制权：人机协同'}</span><span>BAILUWAN OS <b>1.1</b><span className="separator">/</span>连接空间与可能</span></footer>
    </main>
    {selection&&selected&&<Drawer selection={selection} selected={selected} onClose={()=>{setSelection(null);setFloor(0);}} floor={floor} setFloor={setFloor} {...shared}/>}
    {agentOpen&&<AgentPanel {...shared} onClose={()=>setAgentOpen(false)}/>}
    {modal&&<ActionModal modal={modal} onClose={()=>setModal(null)} {...shared}/>}
    <div className="toast-stack" aria-live="polite">{toasts.map(t=><div key={t.id} className={'toast '+t.type}>{t.type==='error'?<ShieldAlert size={18}/>:<CheckCircle2 size={18}/>}<span>{t.message}</span><button onClick={()=>setToasts(v=>v.filter(x=>x.id!==t.id))}><X size={14}/></button></div>)}</div>
  </div>;
}

function Metric({icon:Icon,label,value,unit,foot,trend,accent='',spark}){return <section className={'metric '+accent}><div className="metric-label"><span>{label}</span><Icon size={17}/></div><div className="metric-value">{value}<small>{unit}</small>{spark&&<Sparkline values={spark} fill/>}</div><div className="metric-foot"><span>{foot}</span>{trend&&<em><i/>{trend}</em>}</div></section>}
function PagePanel({eyebrow,title,extra,children}){return <section className="panel management-panel"><div className="management-heading"><div><span className="section-eyebrow">{eyebrow}</span><h2>{title}</h2></div>{extra}</div>{children}</section>}
function DevicePage({data,act,busy,openSelection,canControl,setModal}){const canAutomate=['super_admin','park_admin'].includes(data.user.role);const [filter,setFilter]=useState('all'),[building,setBuilding]=useState('all'),[query,setQuery]=useState(''),[picked,setPicked]=useState([]),[section,setSection]=useState('devices');const devices=data.devices.filter(d=>(filter==='all'||d.type===filter)&&(building==='all'||d.buildingId===building)&&(d.name+d.id).toLowerCase().includes(query.toLowerCase()));return <><div className="subnav"><button className={section==='devices'?'active':''} onClick={()=>setSection('devices')}>设备资产 <span>{data.devices.length}</span></button>{canAutomate&&<button className={section==='automation'?'active':''} onClick={()=>setSection('automation')}>场景与定时策略</button>}<button className={section==='commands'?'active':''} onClick={()=>setSection('commands')}>指令回执</button></div>{section==='devices'?<PagePanel eyebrow="CONNECTED DEVICES" title="设备列表" extra={<span className="tag"><i/>适配器：SIMULATOR</span>}><div className="table-toolbar"><div className="filter-search"><Search size={16}/><input placeholder="搜索设备名称或编号" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="设备类型" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">全部设备类型</option>{Object.entries(types).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select><select aria-label="设备区域" value={building} onChange={e=>setBuilding(e.target.value)}><option value="all">全部建筑区域</option>{data.buildings.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><span className="toolbar-spacer"/><button className="secondary" disabled={!canControl||!picked.length} onClick={()=>setModal({type:'batch',deviceIds:picked})}><Power size={15}/>批量控制 {picked.length>0&&`(${picked.length})`}</button></div><div className="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="选择当前全部设备" checked={devices.length>0&&devices.every(d=>picked.includes(d.id))} onChange={e=>setPicked(e.target.checked?devices.map(d=>d.id):[])}/></th><th>设备名称 / 编号</th><th>设备类型</th><th>所属区域</th><th>运行状态</th><th>实时读数</th><th>操作</th></tr></thead><tbody>{devices.map(d=>{const Icon=icons[d.type]||Radio;return <tr key={d.id}><td><input type="checkbox" aria-label={'选择'+d.name} checked={picked.includes(d.id)} onChange={e=>setPicked(v=>e.target.checked?[...v,d.id]:v.filter(x=>x!==d.id))}/></td><td><div className="table-identity"><span><Icon size={18}/></span><div><strong>{d.name}</strong><small>{d.id}</small></div></div></td><td>{types[d.type]}</td><td>{data.buildings.find(b=>b.id===d.buildingId)?.name||'室外公共区域'}<small className="block muted">{d.floor?`${d.floor}F`:'地面 / 航线'}</small></td><td><Badge status={d.status}/></td><td>{deviceReading(d)}</td><td><button className="text-button mint-text" onClick={()=>openSelection({kind:'device',id:d.id})}>详情与控制 <ChevronRight size={14}/></button></td></tr>})}</tbody></table>{!devices.length&&<Empty text="没有符合筛选条件的设备"/>}</div></PagePanel>:section==='automation'?<PagePanel eyebrow="AUTOMATION POLICIES" title="场景与定时策略"><div className="automation-grid">{data.automations.map(a=><div className="automation-card" key={a.id}><div><div className="automation-icon"><Clock size={22}/></div><button aria-label={(a.enabled?'关闭':'启用')+a.name} className={'switch '+(a.enabled?'on':'')} disabled={!canAutomate||busy||data.takeover.active} onClick={()=>act('/automations/'+a.id,{enabled:!a.enabled})}><i/></button></div><h3>{a.name}</h3><p>{a.schedule||'手动触发'} · {a.mode}</p><small>{a.enabled?'策略已启用，等待满足执行条件':'策略已停用'}</small><button className="text-button" disabled={!canAutomate} onClick={()=>setModal({type:'automation',automation:a})}>配置时间与场景 <Settings2 size={14}/></button></div>)}</div></PagePanel>:<PagePanel eyebrow="COMMAND RECEIPTS" title="指令执行轨迹"><p className="panel-description">提交不等于执行成功。只有设备模拟器返回确认后，指令才会显示“已执行”。</p><div className="table-scroll"><table><thead><tr><th>指令编号</th><th>设备</th><th>操作</th><th>执行状态</th><th>提交时间</th><th>说明</th></tr></thead><tbody>{(data.commands||[]).slice(0,80).map(c=><tr key={c.id}><td className="mono">{c.id.slice(-12)}</td><td>{data.devices.find(d=>d.id===c.deviceId)?.name||c.deviceId}</td><td>{c.action} → {String(c.value)}</td><td><Badge status={c.status}>{c.status==='pending'?'等待设备回执':statusText[c.status]}</Badge></td><td>{fmtTime(c.createdAt)}</td><td>{c.error||c.result||c.message||c.source||'—'}{data.takeover.active&&data.user.role==='super_admin'&&c.status==='pending'&&<button className="text-button amber-text" disabled={busy} onClick={()=>act('/commands/'+c.id+'/cancel',{},'待执行指令已撤销')}>撤销待执行联动</button>}</td></tr>)}</tbody></table>{!data.commands?.length&&<Empty text="尚无设备指令"/>}</div></PagePanel>}</>}
function deviceReading(d){const s=d.state||{};return d.type==='hvac'?`${s.temperature??24} °C / ${s.power?'开启':'关闭'}`:d.type==='light'?`${s.power?'开启':'关闭'} · ${s.brightness??0}%`:d.type==='window'?(s.open?'已开启':'已关闭'):['robot','drone','delivery_robot'].includes(d.type)?`电量 ${Math.round(s.battery??100)}%`:`${s.temperature??'—'} °C · ${Number(s.smoke)>.5?'烟雾异常':'环境正常'}`;}

function SecurityPage({data,setModal,act,busy,openSelection,canSecurity}){const [section,setSection]=useState('events'),[filter,setFilter]=useState('active');const records=data.alerts.filter(a=>filter==='all'||(filter==='fire'?a.type==='fire':a.status!=='archived'));return <><div className="subnav"><button className={section==='events'?'active':''} onClick={()=>setSection('events')}>事件处置中心</button><button className={section==='patrols'?'active':''} onClick={()=>setSection('patrols')}>机器人巡检</button></div>{section==='events'?<PagePanel eyebrow="SECURITY & EMERGENCY" title="事件处置" extra={<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="active">待处置事件</option><option value="fire">消防演练</option><option value="all">全部 / 历史事件</option></select>}><div className="event-grid">{records.map(a=><button className={'event-card '+a.severity} key={a.id} onClick={()=>openSelection({kind:'alert',id:a.id})}><div><span className="event-type">{a.type==='fire'?<Flame size={18}/>:<ShieldAlert size={18}/>} {a.type==='fire'?'消防事件':a.type==='energy'?'能耗异常':'安防事件'}</span><Badge status={a.status}/></div><h3>{a.title}</h3><p>{a.description}</p><div className="event-card-foot"><span><MapPin size={13}/>{data.buildings.find(b=>b.id===a.buildingId)?.name||'园区公共区域'}</span><span>{fmtTime(a.createdAt)} <ChevronRight size={14}/></span></div>{a.drill&&<span className="drill-label">演练 · 模拟数据</span>}</button>)}{!records.length&&<Empty text="当前没有待处置事件" icon={CheckCircle2}/>}</div></PagePanel>:<PagePanel eyebrow="AUTONOMOUS PATROL" title="巡检任务" extra={<button className="primary" disabled={!canSecurity} onClick={()=>setModal({type:'patrol'})}><Plus size={16}/>创建巡检任务</button>}><div className="patrol-grid">{data.patrols.map(p=><div className="patrol-card" key={p.id}><div className="patrol-visual"><Shield size={42}/><span>BLW ROBOT</span><Badge status={p.status}/></div><div className="patrol-card-body"><h3>{p.name}</h3><p>{data.devices.find(d=>d.id===p.robotId)?.name||p.robotId} · 电量 {Math.round(data.devices.find(d=>d.id===p.robotId)?.state?.battery||0)}%</p><div className="progress-line"><span><i style={{width:p.progress+'%'}}/></span><b>{Math.round(p.progress||0)}%</b></div><div className="route-text"><MapPin size={14}/>{(p.route||[]).map(id=>data.buildings.find(b=>b.id===id)?.code||id).join(' → ')}</div><div className="button-row">{p.status==='running'&&<button className="secondary" disabled={busy||!canSecurity} onClick={()=>act(`/patrols/${p.id}/action`,{action:'pause'})}><Pause size={14}/>暂停</button>}{p.status==='paused'&&<button className="secondary" disabled={busy||!canSecurity} onClick={()=>act(`/patrols/${p.id}/action`,{action:'resume'})}><Play size={14}/>继续</button>}{['running','paused','queued'].includes(p.status)&&<button className="secondary" disabled={busy||!canSecurity} onClick={()=>act(`/patrols/${p.id}/action`,{action:'recall'})}><RotateCcw size={14}/>返航</button>}<button className="text-button" onClick={()=>openSelection({kind:'device',id:p.robotId})}>定位机器人 <LocateFixed size={14}/></button></div></div></div>)}</div></PagePanel>}</>}

function DeliveryPage({data,act,busy,setModal,canControl,canSecurity,goLocation}){const [filter,setFilter]=useState('active');const orders=data.deliveries.filter(d=>filter==='all'||!['archived','cancelled'].includes(d.status));const fleet=data.devices.filter(d=>['drone','delivery_robot'].includes(d.type));return <><div className="fleet-row">{fleet.map(d=><div className="fleet-card" key={d.id}><div className="fleet-icon">{d.type==='drone'?<Send size={25}/>:<Truck size={25}/>}</div><div><strong>{d.name}</strong><small>{types[d.type]} · 载重上限 {d.type==='drone'?5:20} kg</small></div><div><Badge status={d.status}/><small>电量 {Math.round(d.state.battery||0)}%</small></div></div>)}</div><PagePanel eyebrow="LAST-MILE LOGISTICS" title="配送订单" extra={<button className="primary" onClick={()=>setModal({type:'dispatchDelivery'})}><Plus size={16}/>发起配送</button>}><div className="table-toolbar"><div className="segmented"><button className={filter==='active'?'active':''} onClick={()=>setFilter('active')}>进行中</button><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>全部订单</button></div><span className="muted">申请单需审批；调度员派单通过校验即出发</span></div><div className="table-scroll"><table><thead><tr><th>订单 / 物品</th><th>配送路线</th><th>运载设备</th><th>任务进度</th><th>状态</th><th>操作</th></tr></thead><tbody>{orders.map(d=><tr key={d.id}><td><strong>{d.title}</strong>{d.routePlan&&<details className="role-record-details"><summary>派单依据与路线</summary><DeliveryRouteSummary order={d}/></details>}<small className="block muted">{d.priority==='urgent'?'优先配送':'普通配送'} · {d.weight} kg · {d.id.slice(-8)}</small></td><td><button className="location-link" onClick={()=>goLocation(d.to)}>{data.buildings.find(b=>b.id===d.from)?.name||d.from}<ArrowRight size={13}/>{data.buildings.find(b=>b.id===d.to)?.name||d.to}</button></td><td>{data.devices.find(v=>v.id===d.vehicleId)?.name||'待分配'}</td><td><div className="progress-line table-progress"><span><i style={{width:(d.progress||0)+'%'}}/></span><b>{Math.round(d.progress||0)}%</b></div><small className="muted">{['delivered','signed','archived'].includes(d.status)?'已抵达终点':d.eta?`预计 ${d.eta} 分钟`:'等待调度'}</small></td><td><Badge status={d.status}/>{(d.exception||d.error)&&<small className="block amber-text">{d.exception||d.error}</small>}</td><td><div className="row-actions">{({queued:['dispatch'],running:['pause','recall'],paused:['resume','recall'],exception:['reassign','cancel'],delivered:['sign'],signed:['archive'],pending_approval:['cancel']}[d.status]||[]).map(action=><button key={action} className="text-button mint-text" disabled={busy} onClick={()=>act(`/deliveries/${d.id}/action`,{action})}>{{dispatch:'调度',pause:'暂停',resume:'继续',recall:'返航',cancel:'取消',sign:'确认签收',archive:'归档',reassign:'异常改派'}[action]}</button>)}</div></td></tr>)}</tbody></table>{!orders.length&&<Empty text="暂无配送任务" icon={Package}/>}</div></PagePanel></>}

function OAPage({data,setModal,act,busy,canApprove}){const [filter,setFilter]=useState('pending'),[expanded,setExpanded]=useState(null);const rows=data.approvals.filter(a=>filter==='all'||a.status==='pending');return <PagePanel eyebrow="CONNECTED WORKFLOW" title="协同，让每一个想法落地" extra={<button className="primary" onClick={()=>setModal({type:'approval'})}><Plus size={16}/>发起申请</button>}><div className="table-toolbar"><div className="segmented"><button className={filter==='pending'?'active':''} onClick={()=>setFilter('pending')}>待处理 <span>{data.approvals.filter(a=>a.status==='pending').length}</span></button><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>全部申请</button></div><span className="muted">审批通过后，由业务后端创建执行任务并回传结果</span></div><div className="approval-list">{rows.map(a=><div className="approval-card" key={a.id}><div className="approval-main"><div className="approval-icon"><FileCheck2 size={21}/></div><button className="approval-summary" onClick={()=>setExpanded(expanded===a.id?null:a.id)}><strong>{a.title}</strong><p>{({maintenance:'设备维修',purchase:'物资采购',delivery:'配送申请',permission:'权限申请',incident:'异常处理'}[a.type])||a.type} <span>·</span> {a.requester} <span>·</span> {fmtDate(a.createdAt)}</p></button><Badge status={a.status}/><IconButton icon={ChevronDown} title="查看申请详情" onClick={()=>setExpanded(expanded===a.id?null:a.id)}/></div>{expanded===a.id&&<div className="approval-detail"><p>{a.description||'关联园区业务申请，审批结果将同步至相关任务。'}</p><div className="detail-kv"><span>关联记录</span><strong>{a.relatedId||'独立申请'}</strong><span>执行反馈</span><strong>{a.result&&typeof a.result==='object'?JSON.stringify(a.result):a.result||'等待审批决策'}</strong></div>{(a.steps||[]).map((s,i)=><div className="approval-step" key={i}><CheckCircle2 size={15}/><span>{typeof s==='string'?s:s.name+' · '+(statusText[s.status]||({waiting:'等待执行',pending:'待审批',running:'执行中'}[s.status])||s.status)}</span></div>)}{a.status==='pending'&&<div className="button-row">{canApprove&&<><button className="primary" disabled={busy} onClick={()=>act(`/approvals/${a.id}/action`,{action:'approve',note:'核验通过，按流程执行'})}><Check size={15}/>同意</button><button className="secondary" onClick={()=>setModal({type:'approvalAction',id:a.id,action:'reject'})}>驳回</button><button className="secondary" onClick={()=>setModal({type:'approvalAction',id:a.id,action:'transfer'})}>转交</button></>}<button className="secondary" disabled={busy} onClick={()=>act(`/approvals/${a.id}/action`,{action:'remind'})}>催办</button><button className="text-button" disabled={busy} onClick={()=>act(`/approvals/${a.id}/action`,{action:'withdraw'})}>撤回申请</button></div>}</div>}</div>)}{!rows.length&&<Empty text="待办已处理完成" icon={CheckCircle2}/>}</div></PagePanel>}

function AttendancePage({data,act,busy,canSecurity}){const counts=['present','late','absent','review'].map(s=>data.attendance.filter(r=>r.status===s).length);return <><div className="attendance-metrics">{[['正常出勤',counts[0],Users],['迟到记录',counts[1],Clock],['缺勤记录',counts[2],ShieldAlert],['待复核',counts[3],FileCheck2]].map(([name,value,Icon])=><Metric key={name} label={name} value={value} unit="人" icon={Icon} foot="模拟排班 / 最小化人员数据"/>)}</div><PagePanel eyebrow="ATTENDANCE & INSPECTION" title="到岗复核" extra={<span className="tag"><LockKeyhole size={13}/>仅展示业务必要信息</span>}><div className="table-scroll"><table><thead><tr><th>人员代号</th><th>所属部门</th><th>排班时间</th><th>到岗时间</th><th>核验位置</th><th>考勤状态</th><th>操作</th></tr></thead><tbody>{data.attendance.map(r=><tr key={r.id}><td><strong>{r.name}</strong></td><td>{r.department}</td><td>{r.shift}</td><td>{r.checkIn||'未记录'}</td><td>{r.checkpoint||'园区东门考勤点'}</td><td><Badge status={r.status}/>{r.reviewedAt&&<small className="block mint-text">已复核 · {fmtTime(r.reviewedAt)}</small>}</td><td>{r.status!=='present'&&<button className="text-button mint-text" disabled={busy||!canSecurity} onClick={()=>act(`/attendance/${r.id}/review`,{note:'人工核验到岗记录，已记录复核意见'})}>{r.reviewedAt?'再次复核':'人工复核'}</button>}</td></tr>)}</tbody></table></div></PagePanel></>}

function ReportsPage({data,notify}){const energy=data.energy||[];const vals=energy.map(v=>v.value??v.kwh??0);const max=Math.max(...vals,1);const [verify,setVerify]=useState(null);function download(){const blob=new Blob([JSON.stringify({generatedAt:new Date().toISOString(),mode:'simulation',energy:data.energy,metrics:data.metrics,patrols:data.patrols,alerts:data.alerts},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='白鹭湾-运行报告.json';a.click();URL.revokeObjectURL(url);notify('运行报告已导出');}return <><div className="reports-grid"><PagePanel eyebrow="ENERGY INSIGHTS" title="用电记录" extra={<span className="tag">模拟采样 / kWh</span>}><div className="energy-summary"><strong>{num(vals.reduce((a,b)=>a+b,0).toFixed(1))}<span>kWh</span></strong><p>今日累计用电 · 当前模拟时段</p></div><div className="energy-chart"><div className="chart-grid"><span>{Math.ceil(max)}</span><span>{Math.ceil(max*.75)}</span><span>{Math.ceil(max*.5)}</span><span>{Math.ceil(max*.25)}</span><span>0</span></div><div className="chart-bars">{energy.map((e,i)=><div key={i}><span style={{height:`${(e.value??e.kwh??0)/max*100}%`}} title={`${e.label}: ${e.value??e.kwh} kWh`}/><small>{e.label}</small></div>)}</div></div><p className="panel-description">由设备模拟器生成的演示数据。正式接入后可映射分项电表、碳排因子及历史基线。</p></PagePanel><PagePanel eyebrow="OPERATIONAL SUMMARY" title="园区运行简报"><div className="report-stat"><span>设备接入</span><strong>{data.devices.length}<small>台</small></strong></div><div className="report-stat"><span>累计巡检任务</span><strong>{data.patrols.length}<small>项</small></strong></div><div className="report-stat"><span>事件闭环归档</span><strong>{data.alerts.filter(a=>a.status==='archived').length}<small>项</small></strong></div><div className="report-stat"><span>审批完成</span><strong>{data.approvals.filter(a=>a.status==='approved').length}<small>项</small></strong></div><button className="secondary full-width" onClick={download}><Download size={16}/>导出运行报告</button></PagePanel></div><PagePanel eyebrow="TRACEABLE OPERATIONS" title="操作审计" extra={<button className="secondary" onClick={async()=>{try{setVerify(await api('/audit/verify'));}catch(e){notify(e.message,'error');}}}><Shield size={15}/>校验审计链</button>}>{verify&&<div className="verify-result"><CheckCircle2 size={16}/>{JSON.stringify(verify)}</div>}<div className="table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>操作类型</th><th>目标</th><th>记录摘要</th><th>链式校验摘要</th></tr></thead><tbody>{(data.audit||[]).slice(0,70).map(a=><tr key={a.id}><td>{fmtDate(a.at)}</td><td>{a.actor}</td><td className="mono">{a.action}</td><td>{a.target||'—'}</td><td className="audit-detail" title={typeof a.detail==='object'?JSON.stringify(a.detail):a.detail}>{typeof a.detail==='object'?JSON.stringify(a.detail):a.detail}</td><td className="mono muted">{a.hash?.slice(0,14)}…</td></tr>)}</tbody></table></div></PagePanel></>}

function Drawer({selection,selected,onClose,data,act,busy,setModal,openSelection,floor,setFloor,canControl,canSecurity}){const [value,setValue]=useState(24),[brightness,setBrightness]=useState(70);useEffect(()=>{setValue(selected.state?.temperature??24);setBrightness(selected.state?.brightness??70)},[selected.id]);const b=data.buildings.find(b=>b.id===(selection.kind==='building'?selected.id:selected.buildingId));const control=async(action,val)=>act('/commands',{deviceIds:[selected.id],action,value:val,idempotencyKey:key()},'指令已提交，等待设备回执');const cmds=(data.commands||[]).filter(c=>c.deviceId===selected.id).slice(0,6),pending=cmds.some(c=>c.status==='pending');const state=selected.state||{};const next={detected:['confirm','确认事件'],confirmed:['dispatch','派单处理'],dispatched:['resolve','提交处置结果'],resolved:['review','复核通过'],reviewed:['archive','归档事件']}[selected.status];return <aside className="detail-drawer" role="dialog" aria-label={selected.name||selected.title}><div className="drawer-top"><span className="section-eyebrow">{selection.kind==='building'?'BUILDING EXPLORER':selection.kind==='device'?'DEVICE COMMAND':'EVENT WORKSPACE'}</span><IconButton icon={X} title="关闭详情" onClick={onClose}/></div><div className="drawer-title"><div className="drawer-icon">{selection.kind==='building'?<Building2 size={27}/>:selection.kind==='alert'?<ShieldAlert size={27}/>:React.createElement(icons[selected.type]||Radio,{size:27})}</div><h2>{selected.name||selected.title}</h2><p><MapPin size={13}/>{b?.name||'园区公共区域'}{selected.floor?` · ${selected.floor}F`:''}<span> / {selected.id}</span></p></div><div className="drawer-content">
  {selection.kind==='building'?<><div className="building-stats"><div><strong>{selected.floors}</strong><span>地上楼层</span></div><div><strong>{selected.occupancy}</strong><span>模拟使用人数</span></div><div><strong>{data.devices.filter(d=>d.buildingId===selected.id).length}</strong><span>接入设备</span></div></div><div className="section-label"><h3>空间与楼层</h3><small>{selected.usage}</small></div><div className="floor-picker"><button className={!floor?'active':''} onClick={()=>setFloor(0)}>整栋</button>{Array.from({length:selected.floors},(_,i)=>i+1).map(f=><button key={f} className={floor===f?'active':''} onClick={()=>setFloor(f)}>{f}F</button>)}</div><p className="help-text">选择楼层以截取三维建筑，并筛选本层设备。</p><div className="section-label"><h3>{floor?floor+'F · ':''}设备清单</h3><span>点击查看</span></div>{data.devices.filter(d=>d.buildingId===selected.id&&(!floor||d.floor===floor)).map(d=><button className="drawer-device-row" key={d.id} onClick={()=>openSelection({kind:'device',id:d.id})}>{React.createElement(icons[d.type]||Radio,{size:17})}<span>{d.name}<small>{deviceReading(d)}</small></span><Badge status={d.status}/></button>)}{!data.devices.some(d=>d.buildingId===selected.id&&(!floor||d.floor===floor))&&<Empty text="本层暂无模拟设备"/>}</>:selection.kind==='device'?<><div className="device-state"><Badge status={selected.status}/><span>最后同步 {fmtTime(selected.updatedAt)}</span></div><div className="telemetry-card"><span>设备实时状态</span><strong>{deviceReading(selected)}</strong><Sparkline fill values={[26,28,25,30,32,29,31,30,29,31]}/><small>上方为实时读数 · 曲线为示意数据</small></div>{selected.capabilities?.some(c=>['power','temperature','brightness','open','mode'].includes(c))&&<><div className="section-label"><h3>设备控制</h3><small>{canControl?'需要设备执行回执':'当前角色仅可查看'}</small></div>{pending&&<div className="notice"><Loader2 size={15} className="spin"/>有指令等待设备回执，暂不可重复提交</div>}{selected.status==='offline'&&<div className="inline-error">设备离线。请先检修通信链路，当前不可控制。</div>}{selected.capabilities.includes('power')&&<div className="control-row"><span>电源开关</span><button className={'switch '+(state.power?'on':'')} disabled={busy||pending||!canControl||selected.status==='offline'} aria-label="切换设备电源" onClick={()=>control('power',!state.power)}><i/></button></div>}{selected.type==='light'&&<div className="control-field"><label>照明亮度 <strong>{brightness}%</strong></label><input type="range" min="0" max="100" value={brightness} onChange={e=>setBrightness(+e.target.value)}/><button className="secondary full-width" disabled={busy||pending||!canControl||selected.status==='offline'} onClick={()=>control('brightness',brightness)}>应用亮度设置</button></div>}{selected.type==='hvac'&&<><div className="control-field"><label>目标温度 <strong>{value} °C</strong></label><input type="range" min="16" max="30" value={value} onChange={e=>setValue(+e.target.value)}/><button className="secondary full-width" disabled={busy||pending||!canControl||selected.status==='offline'} onClick={()=>control('temperature',value)}>应用温度设置</button></div><div className="control-field"><label>运行模式</label><select disabled={busy||pending||!canControl||selected.status==='offline'} value={state.mode||'auto'} onChange={e=>control('mode',e.target.value)}><option value="auto">自动</option><option value="cool">制冷</option><option value="heat">制热</option><option value="fan">送风</option><option value="eco">节能</option></select></div></>}{selected.type==='window'&&<div className="control-row"><span>天窗状态</span><button className="secondary" disabled={busy||pending||!canControl||selected.status==='offline'} onClick={()=>control('open',!state.open)}>{state.open?'关闭天窗':'开启天窗'}</button></div>}</>}{['robot','drone','delivery_robot'].includes(selected.type)&&<div className="notice">无人设备的运行控制请在巡检调度或无人配送中进行，确保任务与设备状态一致。</div>}<div className="section-label"><h3>最近控制记录</h3><History size={15}/></div>{cmds.length?cmds.map(c=><div className="command-row" key={c.id}><div><strong>{c.action} → {String(c.value)}</strong><small>{fmtTime(c.createdAt)} · {c.result||c.error||'等待执行反馈'}</small></div><Badge status={c.status}>{c.status==='pending'?'等待回执':statusText[c.status]}</Badge></div>):<p className="help-text">暂无控制记录。下发指令后将在这里持续更新状态。</p>}</>:<><div className="device-state"><Badge status={selected.status}/><span>{selected.drill?'演练 / 模拟事件':'事件记录'}</span></div><div className="event-evidence"><div className="evidence-grid"/><div className="evidence-box"><ShieldAlert size={25}/><span>{selected.type==='fire'?'SIMULATED FIRE ALERT':'SIMULATED DETECTION'}</span></div><div className="evidence-caption"><span><i/>模拟监控画面</span><span>{b?.code||'PUBLIC'} · CAM-01</span></div></div><p className="event-description">{selected.description}</p><div className="event-steps">{['发现','确认','派单','处理','复核','归档'].map((s,i)=><span key={s} className={['detected','confirmed','dispatched','resolved','reviewed','archived'].indexOf(selected.status)>=i?'done':''}>{i+1}<small>{s}</small></span>)}</div>{selected.emergencySteps&&<div className="emergency-steps">{selected.emergencySteps.map((s,i)=><div key={i}><CheckCircle2 size={14}/><span>{s.name}</span><Badge status={s.status}/></div>)}</div>}{next&&<div className="button-row">{selected.type==='fire'&&(selected.status==='confirmed'||(selected.status==='dispatched'&&selected.emergencySteps?.[2]?.status==='failed'))?<button className="danger full-width" disabled={!['super_admin','park_admin'].includes(data.user.role)||busy} onClick={()=>setModal({type:'emergency',id:selected.id})}><Flame size={16}/>{selected.status==='dispatched'?'重试失败的消防演练联动':'确认执行消防演练预案'}</button>:<button className="primary full-width" disabled={!canSecurity||busy} onClick={()=>setModal({type:'transition',id:selected.id,action:next[0],name:next[1]})}><CheckCircle2 size={16}/>{next[1]}</button>}</div>}<div className="section-label"><h3>处置时间线 / 历史回放</h3><History size={15}/></div><div className="timeline">{[...(selected.timeline||[])].reverse().map((t,i)=><div key={i}><i/><span>{fmtDate(t.at)}</span><strong>{t.actor} · {t.action}</strong><p>{t.note||'操作已记录'}</p></div>)}</div></>}
  </div><div className="drawer-footer"><Shield size={13}/>操作经过业务后端权限校验与审计记录</div></aside>}

function ActionModal({modal,onClose,data,act,busy,notify}){const [name,setName]=useState(''),[note,setNote]=useState(''),[password,setPassword]=useState(''),[from,setFrom]=useState('B03'),[to,setTo]=useState('B06'),[vehicle,setVehicle]=useState(''),[weight,setWeight]=useState(1.5),[priority,setPriority]=useState('normal'),[approvalType,setApprovalType]=useState('maintenance'),[assignee,setAssignee]=useState('U-approver'),[on,setOn]=useState(true),[time,setTime]=useState(modal.automation?.schedule||'08:30'),[mode,setMode]=useState(modal.automation?.mode||'work');let title='',subtitle='',body=null,submit=null,button='确认提交',danger=false;const buildingsOptions=data.buildings.map(b=><option value={b.id} key={b.id}>{b.name}</option>);const finish=async(path,payload,msg)=>{const result=await act(path,payload,msg);if(result)onClose();};
  if(modal.type==='takeover'){title=modal.release?'检查并恢复自动化':'人工最高权限接管';subtitle='身份二次确认 · 操作写入审计链';danger=!modal.release;button=modal.release?'执行恢复检查并解除':'确认接管系统';body=<><div className={'impact-box '+(modal.release?'':'warning')}><ShieldAlert size={24}/><div><strong>{modal.release?'恢复前检查':'接管将立即影响以下运行状态'}</strong><ul>{(modal.release?['高危消防事件必须完成处置与复核','所有待执行设备指令必须收敛','设备模拟器须保持连接；已暂停任务需逐条人工恢复']:['暂停 Agent 工具调用与定时自动化策略','暂停在途巡检与配送，保留进度，支持人工召回','取消尚未执行的自动指令；人工指令继续等待回执']).map(t=><li key={t}>{t}</li>)}</ul></div></div>{!modal.release&&<label>接管原因<textarea required minLength={3} placeholder="例如：消防演练期间统一人工指挥" value={note} onChange={e=>setNote(e.target.value)}/></label>}<label>输入当前管理员密码<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" placeholder="再次确认操作人身份"/></label><p className="help-text">仅超级管理员具备接管权限。系统不会自动恢复已暂停的无人任务。</p></>;submit=()=>finish('/takeover',{action:modal.release?'release':'activate',password,reason:note,confirmed:true},modal.release?'状态检查通过，已解除人工接管':'人工接管已生效，Agent 和自动化已暂停');}
  else if(modal.type==='scenario'){title='模拟事件与消防演练';subtitle='所有演练事件均有清晰标识，不会连接现实设备';body=<div className="scenario-choices"><button type="button" disabled={busy} onClick={()=>finish('/scenarios/security',{},'已生成安防异常，请在事件中心开始处置')}><ShieldAlert size={30}/><strong>安防异常模拟</strong><p>模拟通道阻塞、区域入侵等事件，体验发现到归档的完整闭环。</p><span>创建安防事件 <ArrowRight size={15}/></span></button><button type="button" disabled={busy} onClick={()=>finish('/scenarios/fire',{},'已生成消防演练告警，请确认后执行预案')}><Flame size={30}/><strong>消防应急演练</strong><p>模拟烟温感触发，人工确认后联动广播、照明与新风设备。</p><span>发起消防演练 <ArrowRight size={15}/></span></button></div>;}
  else if(modal.type==='scene'){title='应用'+modal.name;subtitle='区域设备批量控制 · 按设备能力匹配指令';body=<div className="impact-box"><Leaf size={26}/><div><strong>{modal.name}</strong><p>{{work:'开启园区照明与空调，恢复工作时段舒适环境。',off:'关闭日常照明与空调，保留设备状态追踪。',night:'启用低亮度夜间照明，降低空调运行负荷。',eco:'照明降亮度、空调提升目标温度，执行节能策略。'}[modal.mode]}</p><p>离线设备会跳过并记录，执行结果请在“设备控制 → 指令回执”中查看。</p></div></div>;submit=()=>finish('/scenes',{mode:modal.mode,idempotencyKey:key()},'场景指令已提交，等待设备回执');}
  else if(modal.type==='batch'){title='区域设备批量控制';subtitle=`已选择 ${modal.deviceIds.length} 台设备`;body=<><div className="notice">仅支持具备电源控制能力的设备。混合选择传感器、窗户或无人设备时，后端将拒绝本次请求。</div><label>目标状态<select value={String(on)} onChange={e=>setOn(e.target.value==='true')}><option value="true">开启</option><option value="false">关闭</option></select></label></>;submit=()=>finish('/commands',{deviceIds:modal.deviceIds,action:'power',value:on,idempotencyKey:key()},'批量指令已提交，等待设备回执');}
  else if(modal.type==='transition'){title=modal.name;subtitle='事件处置记录将追加到时间线与审计日志';body=<><label>处置说明<textarea required minLength={2} value={note} onChange={e=>setNote(e.target.value)} placeholder="填写现场核验、处理过程或复核结论"/></label>{modal.action==='dispatch'&&<label>处理人员<input value={assignee} onChange={e=>setAssignee(e.target.value)} placeholder="安保值班员"/></label>}</>;submit=()=>finish(`/alerts/${modal.id}/transition`,{action:modal.action,note,assignee},'事件状态已更新');}
  else if(modal.type==='emergency'){title='确认执行消防演练联动';subtitle='高风险操作 · 仅管理员可确认';danger=true;button='确认执行演练预案';body=<><div className="impact-box warning"><Flame size={26}/><div><strong>预案将按以下顺序执行</strong><ol><li>记录人工确认与演练位置</li><li>模拟区域广播和疏散指引</li><li>区域照明开启、空调停止，等待设备回执</li><li>记录救援通知，进入现场处置与复核</li></ol></div></div><p className="help-text">本次操作仅作用于模拟设备。联动执行失败或超时会保留异常，不会显示虚假完成。</p></>;submit=()=>finish(`/emergency/${modal.id}/execute`,{confirmed:true,idempotencyKey:key()},'消防演练预案已发出，等待联动回执');}
  else if(modal.type==='patrol'){title='创建临时巡检任务';subtitle='规划路线并分配空闲巡检机器人';body=<><label>任务名称<input required value={name} onChange={e=>setName(e.target.value)} placeholder="例如：晚间北区安全复查"/></label><label>巡检设备<select value={vehicle} onChange={e=>setVehicle(e.target.value)}><option value="">自动分配可用机器人</option>{data.devices.filter(d=>d.type==='robot').map(d=><option key={d.id} value={d.id}>{d.name} · {Math.round(d.state.battery)}%</option>)}</select></label><div className="notice"><Route size={17}/>默认路线：科创中心 → 研发中心 → 运营中心 → 企业服务中心</div></>;submit=()=>finish('/patrols',{name,robotId:vehicle||undefined,route:['B01','B02','B03','B04']},'巡检任务已创建');}
  else if(modal.type==='delivery'){title='创建配送订单';subtitle='订单审批通过后，可调度无人设备执行';body=<><label>物品 / 任务名称<input required value={name} onChange={e=>setName(e.target.value)} placeholder="例如：研发样品 · 密封保温箱"/></label><div className="form-grid"><label>取件起点<select value={from} onChange={e=>setFrom(e.target.value)}>{buildingsOptions}</select></label><label>配送终点<select value={to} onChange={e=>setTo(e.target.value)}>{buildingsOptions}</select></label><label>物品重量（kg）<input type="number" required min="0.1" max="20" step="0.1" value={weight} onChange={e=>setWeight(+e.target.value)}/></label><label>任务优先级<select value={priority} onChange={e=>setPriority(e.target.value)}><option value="normal">普通</option><option value="urgent">紧急</option></select></label></div><label>运载设备<select value={vehicle} onChange={e=>setVehicle(e.target.value)}><option value="">自动分配可用设备</option>{data.devices.filter(d=>['drone','delivery_robot'].includes(d.type)).map(d=><option key={d.id} value={d.id}>{d.name} · 电量 {Math.round(d.state.battery)}%</option>)}</select></label><p className="help-text">调度前会校验审批、载重、电量、设备冲突及路线阻塞。</p></>;submit=()=>finish('/deliveries',{title:name,from,to,weight,priority,vehicleId:vehicle||undefined},'配送订单已创建，请前往协同办公审批');}
  else if(modal.type==='approval'){title='发起协同申请';subtitle='将申请与设备、事件或业务记录关联';body=<><label>申请标题<input required value={name} onChange={e=>setName(e.target.value)} placeholder="请输入申请事项"/></label><label>流程类型<select value={approvalType} onChange={e=>setApprovalType(e.target.value)}><option value="maintenance">设备维修</option><option value="incident">巡检异常</option><option value="purchase">物资采购</option><option value="permission">权限申请</option></select></label><label>关联设备或事件 ID（可选）<input value={vehicle} onChange={e=>setVehicle(e.target.value)} placeholder="例如：DEV-026 / ALT-001"/></label><label>申请说明<textarea required value={note} onChange={e=>setNote(e.target.value)} placeholder="说明问题、目的及预期结果"/></label><p className="help-text">权限申请仅形成审批记录，不会自动授予更高系统权限。</p></>;submit=()=>finish('/approvals',{title:name,type:approvalType,description:note,relatedId:vehicle||undefined},'申请已提交，等待审批');}
  else if(modal.type==='approvalAction'){title=modal.action==='reject'?'驳回申请':'转交审批';body=<><label>处理意见<textarea required value={note} onChange={e=>setNote(e.target.value)} placeholder="填写处理理由"/></label>{modal.action==='transfer'&&<label>转交审批人<select value={assignee} onChange={e=>setAssignee(e.target.value)}><option value="U-approver">流程审批员</option><option value="U-park">园区管理员</option><option value="U-admin">总控管理员</option></select></label>}</>;submit=()=>finish(`/approvals/${modal.id}/action`,{action:modal.action,note,assignee},'审批流转已记录');}
  else if(modal.type==='automation'){title='配置定时策略';subtitle=modal.automation.name;body=<><label>每日触发时间（Asia/Shanghai）<input type="time" required value={time} onChange={e=>setTime(e.target.value)}/></label><label>执行场景<select value={mode} onChange={e=>setMode(e.target.value)}><option value="work">上班模式</option><option value="off">下班模式</option><option value="night">夜间模式</option><option value="eco">节能模式</option></select></label><div className="notice">人工接管期间策略不会执行。恢复自动化后，只在下一个满足条件的时刻运行。</div></>;submit=()=>finish('/automations/'+modal.automation.id,{enabled:modal.automation.enabled,mode,schedule:time},'定时策略已更新');}
  return <Modal title={title} subtitle={subtitle} onClose={onClose}><form onSubmit={e=>{e.preventDefault();submit?.();}}>{body}{submit&&<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>取消</button><button type="submit" className={danger?'danger':'primary'} disabled={busy}>{busy?<Loader2 size={16} className="spin"/>:danger?<ShieldAlert size={16}/>:<Check size={16}/>} {busy?'正在提交…':button}</button></div>}</form></Modal>}

function AgentPanel({data,act,onClose}){const [prompt,setPrompt]=useState(''),[sending,setSending]=useState(false),[messages,setMessages]=useState([{role:'assistant',text:'你好，我是白鹭湾园区助手。可以为你汇总园区状态、分析能耗或生成巡检简报。低风险照明控制经过后端授权，高风险操作只给出建议。当前为规则模拟模式。'}]);const [showTools,setShowTools]=useState(false);const isAdmin=['super_admin','park_admin'].includes(data.user.role);async function send(text=prompt){if(!text.trim()||sending)return;setPrompt('');setMessages(m=>[...m,{role:'user',text}]);setSending(true);let tool='park.status',input={};if(/能耗|用电|节能/.test(text))tool='energy.analyze';if(/告警|异常|事件/.test(text))tool='alerts.summarize';if(/巡检|报告/.test(text))tool='patrol.report';if(/灯|照明/.test(text)&&/关闭|开启|开灯|关灯/.test(text)){tool='device.control';input={deviceIds:data.devices.filter(d=>d.type==='light'&&d.buildingId==='B01').map(d=>d.id),action:'power',value:!/关闭|关灯/.test(text)};}if(/火灾|消防|应急/.test(text)){tool='emergency.execute';input={alertId:data.alerts.find(a=>a.type==='fire'&&a.status!=='archived')?.id};}const result=await act('/agent/call',{tool,input,context:{requestId:key(),reason:text}},'');if(result){const r=result.result||{};setMessages(m=>[...m,{role:'assistant',text:r.summary||r.proposal||(r.commands?'已提交 '+r.commands.length+' 条照明指令，正在等待设备回执。':JSON.stringify(r)),tool,status:result.status,basis:result.basis,extra:r.recommendations}]);}else setMessages(m=>[...m,{role:'assistant',text:'本次请求未执行。请检查当前角色权限、接管状态及错误提示。',status:'failed',tool}]);setSending(false);}return <aside className="agent-drawer" role="dialog" aria-label="园区智能助手"><div className="agent-drawer-head"><div className="agent-orb"><Sparkles size={23}/></div><div><h2>园区智能助手</h2><span><i/>规则模拟 · 工具调用可追溯</span></div><IconButton icon={X} title="关闭助手" onClick={onClose}/></div><div className="agent-context"><Building2 size={15}/><span>白鹭湾园区</span><span>{data.devices.length} 台设备</span><span>{data.takeover.active?'人工接管中':'权限受控'}</span></div>{(!isAdmin||data.takeover.active)&&<div className="inline-error">{data.takeover.active?'人工接管已暂停全部 Agent 调用':'当前角色没有 Agent 调用权限，请使用管理员角色。'}</div>}<div className="chat-messages">{messages.map((m,i)=><div key={i} className={'chat-message '+m.role}>{m.role==='assistant'&&<span className="assistant-avatar"><Sparkles size={15}/></span>}<div><p>{m.text}</p>{m.extra&&<ul>{m.extra.map(x=><li key={x}>{x}</li>)}</ul>}{m.tool&&<div className="tool-receipt"><Terminal size={12}/><span>{m.tool}</span><Badge status={m.status}>{m.status==='requires_confirmation'?'待人工确认':m.status==='succeeded'?'调用完成':'调用失败'}</Badge></div>}{m.basis&&<small className="basis">{m.basis}</small>}</div></div>)}{sending&&<div className="assistant-thinking"><Loader2 size={16} className="spin"/>正在校验授权并调用业务工具…</div>}</div><div className="agent-suggestions">{['园区当前状态','汇总待处置告警','分析今日能耗','生成巡检报告'].map(s=><button key={s} disabled={sending||!isAdmin||data.takeover.active} onClick={()=>send(s)}>{s}<ArrowUpRight size={12}/></button>)}</div><form className="agent-input" onSubmit={e=>{e.preventDefault();send();}}><textarea aria-label="输入园区指令" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="例如：关闭科创中心照明" disabled={!isAdmin||data.takeover.active} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}}}/><button type="submit" aria-label="发送指令" disabled={sending||!isAdmin||data.takeover.active||!prompt.trim()}><ArrowUpRight size={18}/></button></form><button className="agent-audit-link" onClick={()=>setShowTools(!showTools)}><History size={13}/>查看最近工具调用与审计记录 <ChevronDown size={13}/></button>{showTools&&<div className="agent-audit-list">{(data.agentRuns||[]).slice(0,6).map(r=><div key={r.id}><span>{r.tool}</span><small>{fmtTime(r.at)} · {r.status}</small></div>)}</div>}<div className="agent-disclaimer"><LockKeyhole size={11}/>大模型不得直接连接设备；权限由业务后端固定</div></aside>}
